package br.com.equilibra.creditcard.application;
import br.com.equilibra.creditcard.api.*; import br.com.equilibra.creditcard.domain.*; import br.com.equilibra.creditcard.infrastructure.*; import br.com.equilibra.shared.api.CurrentUser; import br.com.equilibra.shared.web.exception.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service public class CreditCardStatementService{
 private final CreditCardRepository cards; private final CreditCardStatementRepository statements; private final InstallmentRepository installments; private final CurrentUser user;
 public CreditCardStatementService(CreditCardRepository c,CreditCardStatementRepository s,InstallmentRepository i,CurrentUser u){cards=c;statements=s;installments=i;user=u;}
 @Transactional public CreditCardStatementResponse close(String cardId,CloseStatementRequest request){String owner=owner(); CreditCard card=cards.findByIdAndOwnerId(cardId,owner).orElseThrow(()->new ResourceNotFoundException("Credit card not found.")); LocalDate month=request.cycleMonth().withDayOfMonth(1); LocalDate end=month.withDayOfMonth(Math.min(card.getClosingDay(),month.lengthOfMonth())); LocalDate start=month.minusMonths(1).withDayOfMonth(Math.min(card.getClosingDay(),month.minusMonths(1).lengthOfMonth())).plusDays(1); LocalDate due=month.withDayOfMonth(Math.min(card.getDueDay(),month.lengthOfMonth())); Instant closing=end.atStartOfDay(ZoneId.of(card.getTimezone())).toInstant(); CreditCardStatement s=statements.lockCycle(owner,cardId,start,end).orElseGet(()->statements.save(new CreditCardStatement(owner,cardId,start,end,closing,due))); var items=installments.findAllByOwnerIdAndCreditCardIdAndCycleMonthAndStatementIdIsNull(owner,cardId,month); items.forEach(i->i.assignStatement(s.getId())); installments.saveAll(items); BigDecimal total=items.stream().map(Installment::getPrincipalAmount).reduce(BigDecimal.ZERO,BigDecimal::add); if(s.getStatus()==CreditCardStatementStatus.OPEN)s.close(total); return response(s,installments.findAllByOwnerIdAndStatementIdOrderBySequenceNumberAsc(owner,s.getId())); }
 @Transactional(readOnly=true) public List<CreditCardStatementResponse> list(String cardId){String o=owner();cards.findByIdAndOwnerId(cardId,o).orElseThrow(()->new ResourceNotFoundException("Credit card not found."));return statements.findAllByOwnerIdAndCreditCardIdOrderByCycleStartDesc(o,cardId).stream().map(s->response(s,installments.findAllByOwnerIdAndStatementIdOrderBySequenceNumberAsc(o,s.getId()))).toList();}
 @Transactional(readOnly=true) public CreditCardStatementResponse get(String id){String o=owner();CreditCardStatement s=statements.findByIdAndOwnerId(id,o).orElseThrow(()->new ResourceNotFoundException("Statement not found."));return response(s,installments.findAllByOwnerIdAndStatementIdOrderBySequenceNumberAsc(o,id));}
 private CreditCardStatementResponse response(CreditCardStatement s,List<Installment> items){return new CreditCardStatementResponse(s.getId(),s.getCreditCardId(),s.getCycleStart(),s.getCycleEnd(),s.getClosingAt(),s.getDueDate(),s.getStatus(),s.getTotalAmount(),s.getPaidAmount(),s.getOutstandingAmount(),items.stream().map(i->new CreditCardStatementResponse.Item(i.getId(),i.getPurchaseId(),i.getSequenceNumber(),i.getTotalInstallments(),i.getPrincipalAmount(),i.getCycleMonth())).toList());}
 private String owner(){return user.id().toString();}
}
